package com.yeyamo_mobile.api.notification_service.infrastructure.channel;
import java.util.Map;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.MediaType;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import com.yeyamo_mobile.api.notification_service.application.port.ChannelSender;import com.yeyamo_mobile.api.notification_service.domain.NotificationChannel;
@Component public class PushChannelSender implements ChannelSender{private final RestClient client=RestClient.create();private final String endpoint;private final String apiKey;public PushChannelSender(@Value("${notification.push.endpoint:}")String endpoint,@Value("${notification.push.api-key:}")String key){this.endpoint=endpoint;apiKey=key;}public NotificationChannel channel(){return NotificationChannel.PUSH;}public void send(String destination,String subject,String body,String data){if(endpoint==null||endpoint.isBlank())throw new IllegalStateException("Push provider is not configured");client.post().uri(endpoint).contentType(MediaType.APPLICATION_JSON).header("Authorization","Bearer "+apiKey).body(Map.of("token",destination,"title",subject,"body",body,"data",data)).retrieve().toBodilessEntity();}}
